#!/usr/bin/env node
'use strict';
// The plugin is a public repository: no project's AGENTS.md or CLAUDE.md, or a part of one, may land in it.
//   P2  no AGENTS.md or AGENTS.override.md outside tests/fixtures/, and no file that starts with the marker line of
//       scripts/agents-md.js outside tests/fixtures/ (a generated file copied in from a project)
//   P2  the detector fires on a planted sample (a root AGENTS.md, a generated file under another name)
const fs = require('fs');
const path = require('path');
const { execFileSync } = require('child_process');
const { ok, done } = require('./lib');

const ROOT = path.join(__dirname, '..');
const files = execFileSync('git', ['-C', ROOT, 'ls-files', '--cached', '--others', '--exclude-standard', '-z'], { encoding: 'utf8' })
  .split('\0').filter(Boolean).filter((f) => fs.existsSync(path.join(ROOT, f)));
const MARKER = /^<!-- codis-agents agents-md v\d+;/;
const NAME = /(^|\/)AGENTS(\.override)?\.md$/i;
const allowed = (f) => f.startsWith('tests/fixtures/');
function offenders(list, read) {
  const hits = [];
  for (const f of list) {
    if (allowed(f)) continue;
    if (NAME.test(f)) { hits.push(`${f} (name)`); continue; }
    let head = '';
    try { head = read(f).slice(0, 200); } catch { continue; }
    if (MARKER.test(head)) hits.push(`${f} (generated by agents-md)`);
  }
  return hits;
}
const readTree = (f) => { const b = fs.readFileSync(path.join(ROOT, f)); return b.slice(0, 200).toString('utf8'); };
const hits = offenders(files, readTree);
ok('P2. no AGENTS.md, AGENTS.override.md or generated agents-md file outside tests/fixtures/', !hits.length, hits.join(', '));
const sample = { 'AGENTS.md': '# rules\n', 'docs/rules.md': '<!-- codis-agents agents-md v1; source: CLAUDE.md; sha256: 00; x -->\nbody\n', 'tests/fixtures/x/AGENTS.md': 'fixture\n', 'sub/agents.override.md': '' };
const s = offenders(Object.keys(sample), (f) => sample[f]);
ok('P2. the detector fires on planted samples and spares tests/fixtures/', s.length === 3 && s.some((x) => x.startsWith('AGENTS.md')) && s.some((x) => x.startsWith('docs/rules.md'))
  && s.some((x) => x.startsWith('sub/agents.override.md')), s.join(', '));
done();
